"""Explicit70374 product facts and source wiring; no client/keys/process execution."""
from pathlib import Path
import hashlib,importlib.util,json,unittest
ROOT=Path(__file__).resolve().parents[2]
class ProductV10Contract(unittest.TestCase):
    @classmethod
    def setUpClass(cls):cls.v=json.loads((ROOT/'contracts/forever-product-contract-v10.json').read_bytes())
    def test_new_profile_target_catalog_and_exact_db2_scope(self):
        v=self.v;self.assertEqual((v['version'],v['contract'],v['publication_profile']),(10,'forever-product-v10','Build70374Db2OnlyV1'));self.assertEqual(v['builds'],[70374]);self.assertEqual(v['plan']['components'],['db2']);self.assertEqual(v['plan']['component_mask'],1);self.assertEqual(v['platform'],'linux');self.assertEqual(v['backend'],'rust-local')
    def test_new_provenance_is_exact_and_independent(self):
        raw=(ROOT/'contracts/wowdbdefs-70374-v1.json').read_bytes();facts=json.loads(raw);c=self.v['plan']['schema_catalog'];self.assertEqual(c['id'],'wowdbdefs-70374-v1');self.assertEqual(c['required_build'],70374);self.assertEqual(c['table_count'],1161);self.assertEqual(c['source_commit'],facts['source']['commit']);self.assertEqual(c['source_blob'],facts['source']['manifest_blob']);self.assertEqual(c['source_sha256'],facts['source']['manifest_sha256']);self.assertEqual(c['facts_sha256'],hashlib.sha256(raw).hexdigest());self.assertNotEqual(c['source_commit'],json.loads((ROOT/'contracts/forever-product-contract-v9.json').read_bytes())['plan']['schema_catalog']['source_commit'])
    def test_old_versions_components_and_wire_formats_remain_separate(self):
        old=json.loads((ROOT/'contracts/forever-product-contract-v5.json').read_bytes());v9=json.loads((ROOT/'contracts/forever-product-contract-v9.json').read_bytes());self.assertEqual(self.v['package'],old['package']);self.assertEqual(self.v['provided_keys'],old['provided_keys']);self.assertEqual(old['builds'],[70338]);self.assertEqual(v9['builds'],[70338]);self.assertEqual(v9['plan']['components'],['db2','gt','cameras']);self.assertEqual(self.v['legacy_preservation']['canonical_versions'],[1,2,3,4,5,6,8,9]);self.assertTrue(self.v['legacy_preservation']['catalog_does_not_select_v10']);self.assertEqual(self.v['failure_envelope'],'forever-product-v10 after valid plan admission; generic CLI/plan failures before admission retain forever-product-v1; all errors path-free');self.assertIn('complete canonical plan SHA-256',self.v['identities']['keys']);self.assertIn('complete canonical plan SHA-256',self.v['identities']['schema_catalog']);self.assertNotIn('v5',self.v['identities']['keys']);self.assertNotIn('v5',self.v['identities']['schema_catalog'])
    def test_existing_db2_policies_caps_and_false_completion(self):
        old=json.loads((ROOT/'contracts/forever-product-contract-v5.json').read_bytes());normalized=json.loads(json.dumps(self.v['limits']).replace('70374','70338'));self.assertEqual(normalized,old['limits']);self.assertFalse(self.v['full_extractor_complete']);self.assertEqual(self.v['limits']['db2_file_bytes'],16*1024**2);self.assertEqual(self.v['limits']['db2_total_bytes'],16*1024**3)
    def test_both_canonical_authored_key_policies(self):
        folder=ROOT/'tests/contracts/fixtures/forever-product-v10';a=(folder/'disabled.tsv').read_text();b=(folder/'provided.tsv').read_text();self.assertEqual(a.replace('decryption\tdisabled','decryption\tprovided-salsa20-v1'),b)
        for data in (a,b):
            self.assertTrue(data.endswith('\n'));self.assertTrue(data.startswith('forever-product\t10\nbuild\t70374\n'));self.assertIn('schema-catalog\twowdbdefs-70374-v1\n',data);self.assertIn('components\tdb2\n',data);self.assertIn('terrain\tnone\n',data);self.assertIn('navigation\tnone\n',data);self.assertNotIn('collision-storage',data);self.assertEqual([line.split('\t',1)[0]for line in data.splitlines() if not line.startswith('db2\t')],self.v['plan']['ordered_keys'])
    def test_scoped_bootstrap_keeps_global_native_admission_closed(self):
        source=(ROOT/'crates/forever-casc/src/admission.rs').read_text();legacy=source.split('pub const SUPPORTED_CLIENTS:',1)[1].split('];',1)[0];self.assertNotIn('70374',legacy);self.assertIn('admit_db2_70374',source);self.assertIn('open_db2_70374', (ROOT/'crates/forever-extractor/src/driver.rs').read_text());self.assertIn('Build70374Db2OnlyV1',(ROOT/'crates/forever-extractor/src/plan/publication.rs').read_text())
    def test_linux_hosted_contract_step_selects_new_suite(self):
        flow=json.loads((ROOT/'.github/workflows/forever-rust.yml').read_bytes());step=next(s for s in flow['jobs']['linux']['steps']if s.get('name')=='Check source contracts and synthetic Python oracle');self.assertIn('python -m unittest discover -s tests/contracts -p test_forever_product_v10_contract.py -v',step['run'].splitlines())
    def test_current_recipe_selects_new_sources_without_version_bump(self):
        spec=importlib.util.spec_from_file_location('product10_packager',ROOT/'tools/package_forever.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);selected=set(m.selected_paths(ROOT));self.assertEqual(m.SOURCE_PROFILE,'forever-seven-crate-linux-product-db2-catalog-source-v10')
        for name in ['contracts/wowdbdefs-70374-v1.json','contracts/forever-product-contract-v10.json','crates/forever-db2/src/records/wowdbdefs_70374_generated.rs','crates/forever-extractor/src/plan/v10_tests.rs','crates/forever-extractor/src/verify/v10.rs','crates/forever-extractor/src/verify/tests/v10.rs','crates/forever-extractor/tests/product_v10_cli.rs','tests/contracts/fixtures/forever-product-v10/disabled.tsv','tests/contracts/fixtures/forever-product-v10/provided.tsv','tests/contracts/test_forever_product_v10_contract.py']:self.assertIn(name,selected)
if __name__=='__main__':unittest.main()
